// src/components/ChordCard.js

import React from 'react';
import { chordDiagrams } from '../data/vocabulary';

const ChordCard = ({ chordName }) => {
  const diagrams = chordDiagrams[chordName];
  if (!diagrams) return null;

  return (
    <div className="chord-card">
      {/* Заголовок - название аккорда */}
      <h3 className="chord-name">{chordName}</h3>

      {/* Контейнер для схем, теперь каждая схема - это отдельный блок на всю ширину */}
      <div className="diagrams-container">
        {diagrams.map((diagram, index) => (
          <div key={index} className="diagram-string">
            {/* Отображаем строку схемы */}
            {diagram}
          </div>
        ))}
      </div>
    </div>
  );
};

export default ChordCard;
